import{_ as e,o as t,c as o,a0 as i}from"./chunks/framework.CzVS_xMp.js";const m=JSON.parse('{"title":"Lab: Communication and Computation Overlap","description":"","frontmatter":{},"headers":[],"relativePath":"systems-performance/labs/ch04/communication-overlap/index.md","filePath":"systems-performance/labs/ch04/communication-overlap/index.md","lastUpdated":1788490169000}'),n={name:"systems-performance/labs/ch04/communication-overlap/index.md"};function s(r,a,l,h,p,c){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="lab-communication-and-computation-overlap" tabindex="-1">Lab: Communication and Computation Overlap <a class="header-anchor" href="#lab-communication-and-computation-overlap" aria-label="Permalink to &quot;Lab: Communication and Computation Overlap&quot;">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Show why Chapter 4 focuses on <strong>exposed communication time</strong>. The total communication volume may be the same, but the optimized path starts each bucket transfer as soon as that gradient bucket is ready.</p><p>This lab is a portable analogue of no-overlap and overlap-enabled DDP training paths.</p><h2 id="baseline" tabindex="-1">Baseline <a class="header-anchor" href="#baseline" aria-label="Permalink to &quot;Baseline&quot;">​</a></h2><p>The baseline runs all backward-layer compute first, then synchronizes every gradient bucket. Communication is fully exposed at the end of the step.</p><h2 id="optimized" tabindex="-1">Optimized <a class="header-anchor" href="#optimized" aria-label="Permalink to &quot;Optimized&quot;">​</a></h2><p>The optimized path submits a bucket transfer immediately after each layer finishes. Later backward compute overlaps with earlier bucket communication, so only the final communication tail remains exposed.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare.py</span></span></code></pre></div><h2 id="expected-observation" tabindex="-1">Expected Observation <a class="header-anchor" href="#expected-observation" aria-label="Permalink to &quot;Expected Observation&quot;">​</a></h2><p>Both paths produce the same checksum. The optimized path should report lower median step time and a higher overlap ratio.</p><h2 id="what-this-proves" tabindex="-1">What This Proves <a class="header-anchor" href="#what-this-proves" aria-label="Permalink to &quot;What This Proves&quot;">​</a></h2><p>Overlap does not make communication disappear. It moves communication under useful compute so the training step pays only the part that cannot be hidden.</p>',14)])])}const u=e(n,[["render",s]]);export{m as __pageData,u as default};
